/**
 * Repoints every `issue_labels` row from `sourceLabelId` to `targetLabelId`
 * and removes the source label. Rows whose issue already carries the target
 * are dropped rather than updated, since `(issue_id, label_id)` is unique.
 */
export async function mergeLabels(
  orgId: OrgId,
  sourceLabelId: LabelId,
  targetLabelId: LabelId,
): Promise<number> {
  const db = getDb();

  const sourceRows = db
    .select({ issueId: issueLabels.issueId })
    .from(issueLabels)
    .where(
      and(
        orgPredicate(issueLabels.orgId, orgId),
        eq(issueLabels.labelId, sourceLabelId),
      ),
    )
    .all();
  const issuesRelabelled = sourceRows.length;

  if (issuesRelabelled > 0) {
    const issueIds = sourceRows.map((row) => row.issueId);
    const targetRows = db
      .select({ issueId: issueLabels.issueId })
      .from(issueLabels)
      .where(
        and(
          orgPredicate(issueLabels.orgId, orgId),
          eq(issueLabels.labelId, targetLabelId),
          inArray(issueLabels.issueId, issueIds),
        ),
      )
      .all();
    const alreadyTargeted = new Set(targetRows.map((row) => row.issueId));
    const toRetarget = issueIds.filter((id) => !alreadyTargeted.has(id));

    if (toRetarget.length > 0) {
      db.update(issueLabels)
        .set({ labelId: targetLabelId })
        .where(
          and(
            orgPredicate(issueLabels.orgId, orgId),
            eq(issueLabels.labelId, sourceLabelId),
            inArray(issueLabels.issueId, toRetarget),
          ),
        )
        .run();
    }

    db.delete(issueLabels)
      .where(
        and(
          orgPredicate(issueLabels.orgId, orgId),
          eq(issueLabels.labelId, sourceLabelId),
        ),
      )
      .run();
  }

  db.delete(labels)
    .where(and(orgPredicate(labels.orgId, orgId), eq(labels.id, sourceLabelId)))
    .run();

  return issuesRelabelled;
}

/** Replaces the whole label set of one issue in a single round trip. */

